"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31549],{74169:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ToolGripService","desc":"Fixes the `RightGrip` of every Tool a player holds:\\n- Moves `C0` (the hand\'s `RightGripAttachment`) to where it is on the block\\n  R15 rig, scaled by the hand size. Avatar bundles move that attachment, so\\n  without this the weapon sits off the pose the hold animations were made for.\\n  The holder\'s weapon pose (`WeaponPose` attribute) moves the hand on the gun\\n  (`WeaponPose.gripFor`) and sizes a pose weapon (`Tool:ScaleTo`, so every\\n  player sees it; `C1` = the scaled `Tool.Grip`). A pose change re-applies\\n  both to the held Tool.\\n- If the Tool has moving parts (a Motor6D under its `Handle`), turns the\\n  Weld into a Motor6D with the same C0/C1. The Animator only reaches a\\n  joint through a chain of Motor6Ds from the character, so this lets the\\n  Fire / Reload animations (`WeaponAnims`) move the weapon parts.\\n- A gun-rig weapon (`GunRig.Uses`) does not hang from the hand: the weld is\\n  destroyed and `GunRig.Attach` joins the Handle to the UpperTorso (`GunJoint`)\\n  and adds the `LeftHandIK` target. `GunJoint` is destroyed when the Tool leaves\\n  the character. A rig that cannot be measured keeps the hand weld.","realm":["Server"],"source":{"line":23,"path":"src/ServerScriptService/ToolGripService.server.luau"}}')}}]);